t = t[:start] + '''def decode_captures(job, probes):
    """Independent transport + record path; returns (rows, rejected, error)."""
    import csv as csv_module
    import io
    sys.path.insert(0, '/workspace/deps')
    import zstandard as zstd
    rows = []
    rejected = []
    chunks = 0
    decoded_total = 0
    plain_total = 0
    try:
        for number, capture in enumerate(job['captures']):
            if capture['encoding'] not in ('csv', 'zstd'):
                raise Bad('encoding')
            chunks += len(capture['chunks'])
            if chunks > 1024:
                raise Bad('chunk budget')
            try:
                blob = b''.join(base64.b64decode(c.encode('ascii'), validate=True)
                                for c in capture['chunks'])
            except Exception:
                raise Bad('base64')
            decoded_total += len(blob)
            if decoded_total > 32 * 1024 ** 2:
                raise Bad('decoded budget')
            if capture['encoding'] == 'zstd':
                plain = zstd.ZstdDecompressor().stream_reader(
                    io.BytesIO(blob), read_across_frames=True).read()
            else:
                plain = blob
            plain_total += len(plain)
            if plain_total > 128 * 1024 ** 2:
                raise Bad('plain budget')
            text = plain.decode('utf-8')
            reader = csv_module.reader(io.StringIO(text, newline=''), strict=True)
            if next(reader, None) != COLS:
                raise Bad('header')
            for ordinal, values in enumerate(reader):
                if any(len(v.encode('utf-8')) > 131072 for v in values):
                    raise Bad('field budget')
                try:
                    rows.append(parse_row(values, job, probes))
                except Bad:
                    rejected.append([number, ordinal])
                except Exception:
                    rejected.append([number, ordinal])
        return rows, rejected, None
    except Bad:
        return None, None, 'capture'
    except csv_module.Error:
        return None, None, 'capture'
    except UnicodeError:
        return None, None, 'capture'
    except Exception:
        return None, None, 'capture'
'''
p.write_text(t)
